import sys; sys.path.insert(0, sys.argv[1])
import sqlite3
from adminhub import db, users, api, audit
from tests.conftest import SAMPLE_USERS
def fresh():
    c = db.connect(":memory:")
    for e,n,r,t in SAMPLE_USERS: users.create_user(c,e,n,r,t)
    return c
c=fresh()
print("pages 5/per2:", api.list_users(c, {"per_page":"2"})["body"]["pages"])
print("pages 5/per25:", api.list_users(c, {})["body"]["pages"])
try: print("per_page 0:", api.list_users(c, {"per_page":"0"}))
except Exception as e: print("per_page 0 raises", type(e).__name__, e)
try: print("page abc:", api.list_users(c, {"page":"abc"}))
except Exception as e: print("page abc raises", type(e).__name__)
print("page 0:", [u["id"] for u in api.list_users(c, {"page":"0","per_page":"2"})["body"]["users"]])
print("per_page -1:", len(api.list_users(c, {"per_page":"-1"})["body"]["users"]))
print("inject:", [u["email"] for u in api.search(c, {"q":"zzz' OR 1=1 --"})["body"]["users"]])
try: print(api.search(c, {"q":"o'brien"}))
except Exception as e: print("quote raises", type(e).__name__, e)
print("wildcard %:", len(api.search(c, {"q":"%"})["body"]["users"]))
print("search has pages key:", "pages" in api.search(c, {"q":"example"})["body"])
# audit swallow
c2=fresh(); c2.execute("DROP TABLE audit_log")
print("bulk w/o audit table:", users.deactivate_users(c2,[1],actor="root"), users.get_user(c2,1).active)
# rowcount with unknown id
c3=fresh(); print("bulk [1,99]:", users.deactivate_users(c3,[1,99],actor="root"), c3.execute("select count(*) from audit_log").fetchone()[0])
c3b=fresh(); users.deactivate_users(c3b,[2],actor="r"); print("bulk already-inactive:", users.deactivate_users(c3b,[2],actor="r"), c3b.execute("select count(*) from audit_log").fetchone()[0])
try: print(api.bulk_deactivate(fresh(), {"ids":["1"]}))
except Exception as e: print("no actor raises", type(e).__name__)
try: print(api.bulk_deactivate(fresh(), {"ids":["x"],"actor":"r"}))
except Exception as e: print("bad id raises", type(e).__name__)
c4=fresh(); users.deactivate_user(c4,3); print("single deactivate audited:", c4.execute("select count(*) from audit_log").fetchone()[0])
print("bulk dup ids:", users.deactivate_users(fresh(),[1,1],actor="r"))
EOF
